import itertools

def fast_roman_subsets(n, adj):
    mask = [0]*n
    for i in range(n):
        m = 1 << i
        for j in adj[i]: m |= (1 << j)
        mask[i] = m
    best = n
    for size in range(1, (best // 2) + 1):
        for Y in itertools.combinations(range(n), size):
            cov = 0
            for y in Y: cov |= mask[y]
            w = 2 * size + n - bin(cov).count("1")
            if w < best:
                best = w
    return best

def bfs(n, adj, s):
    d = [-1]*n
    d[s] = 0
    q = [s]
    for u in q:
        for v in adj[u]:
            if d[v] == -1:
                d[v] = d[u] + 1
                q.append(v)
    return d

